window.CFA_LESSONS=(window.CFA_LESSONS||[]).concat([{"module_id":"CFA26-06-13","title":"Curve-Based and Empirical Fixed-Income Risk Measures","version":"2026","source_basis":[{"source_id":"CFAI","pdf_pages":[331,354],"relation":"primary"},{"source_id":"Kaplan","pdf_pages":[111,117],"relation":"supplementary"},{"source_id":"SAPP","pdf_pages":[365,388],"relation":"supplementary"}],"los_coverage":[{"los_id":"CFA26-06-13-LOS01","status":"targeted_three_source_and_independent_math_QA_pass","learning_goal_vi":"Giải thích vì sao effective duration và effective convexity phù hợp với bond có embedded options.","competency_criteria":["Bám sát LOS CFA Institute 2026","Đối chiếu Kaplan và SAPP theo trang nguồn","Có ví dụ áp dụng và lỗi thường gặp","Có câu hỏi với giải thích đáp án","Kiểm tra phép tính độc lập và tính toàn vẹn website"],"concept_ids":["S01-01","S01-02","S01-03","S01-04","S01-05","S01-06","S01-07","S01-08"],"formula_ids":["F01-01","F01-02"],"example_ids":["E01-01","E01-02"],"question_ids":["Q01-01","Q01-02","Q01-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V6_FI_ONLINE.pdf","pdf_page":335},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book3.pdf","pdf_page":111},"SAPP_2026":{"file":"SAPP Fixed Income.pdf","pdf_page":369}},"missing_items":[]},{"los_id":"CFA26-06-13-LOS02","status":"targeted_three_source_and_independent_math_QA_pass","learning_goal_vi":"Tính biến động giá trái phiếu theo benchmark yield shock khi biết effective duration và convexity.","competency_criteria":["Bám sát LOS CFA Institute 2026","Đối chiếu Kaplan và SAPP theo trang nguồn","Có ví dụ áp dụng và lỗi thường gặp","Có câu hỏi với giải thích đáp án","Kiểm tra phép tính độc lập và tính toàn vẹn website"],"concept_ids":["S02-01","S02-02","S02-03","S02-04","S02-05","S02-06","S02-07"],"formula_ids":["F02-01","F02-02"],"example_ids":["E02-01","E02-02"],"question_ids":["Q02-01","Q02-02","Q02-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V6_FI_ONLINE.pdf","pdf_page":340},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book3.pdf","pdf_page":111},"SAPP_2026":{"file":"SAPP Fixed Income.pdf","pdf_page":379}},"missing_items":[]},{"los_id":"CFA26-06-13-LOS03","status":"targeted_three_source_and_independent_math_QA_pass","learning_goal_vi":"Định nghĩa key rate duration và áp dụng cho sự dịch chuyển không song song của yield curve.","competency_criteria":["Bám sát LOS CFA Institute 2026","Đối chiếu Kaplan và SAPP theo trang nguồn","Có ví dụ áp dụng và lỗi thường gặp","Có câu hỏi với giải thích đáp án","Kiểm tra phép tính độc lập và tính toàn vẹn website"],"concept_ids":["S03-01","S03-02","S03-03","S03-04","S03-05","S03-06","S03-07"],"formula_ids":["F03-01","F03-02","F03-03"],"example_ids":["E03-01","E03-02"],"question_ids":["Q03-01","Q03-02","Q03-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V6_FI_ONLINE.pdf","pdf_page":343},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book3.pdf","pdf_page":114},"SAPP_2026":{"file":"SAPP Fixed Income.pdf","pdf_page":381}},"missing_items":[]},{"los_id":"CFA26-06-13-LOS04","status":"targeted_three_source_and_independent_math_QA_pass","learning_goal_vi":"Mô tả sự khác biệt giữa empirical duration và analytical duration.","competency_criteria":["Bám sát LOS CFA Institute 2026","Đối chiếu Kaplan và SAPP theo trang nguồn","Có ví dụ áp dụng và lỗi thường gặp","Có câu hỏi với giải thích đáp án","Kiểm tra phép tính độc lập và tính toàn vẹn website"],"concept_ids":["S04-01","S04-02","S04-03","S04-04","S04-05","S04-06","S04-07"],"formula_ids":["F04-01","F04-02"],"example_ids":["E04-01","E04-02"],"question_ids":["Q04-01","Q04-02","Q04-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V6_FI_ONLINE.pdf","pdf_page":348},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book3.pdf","pdf_page":115},"SAPP_2026":{"file":"SAPP Fixed Income.pdf","pdf_page":385}},"missing_items":[]}],"sections":[{"heading_vi":"Tại sao yield duration không đủ","body_vi":"Yield-based modified duration và convexity giả định các cash flows dự kiến không đổi khi tăng hoặc giảm own YTM. Trái phiếu callable, putable hoặc MBS có embedded options tạo ra uncertainty vì dòng tiền có thể biến đổi theo lãi suất. Do đó chỉ chiết khấu lại một bộ cash flows cố định sẽ đánh giá sai cả chiều và mức độ rủi ro.","id":"S01-01","los_ids":["CFA26-06-13-LOS01"]},{"heading_vi":"Effective duration","body_vi":"Effective duration đo độ nhạy full price khi benchmark yield curve dịch chuyển một lượng nhỏ, trong khi cash-flow model được định giá lại có tính đến việc nhà phát hành/người vay thay đổi hành vi theo lãi suất. Công thức dùng V_minus, V_plus từ mô hình pricing, không nhất thiết giống modified duration theo YTM.","id":"S01-02","los_ids":["CFA26-06-13-LOS01"]},{"heading_vi":"Effective convexity","body_vi":"Effective convexity dùng sai phân bậc hai đối với benchmark curve shock, vẫn dùng P0 làm cơ sở và ∆curve². Nó có thể âm với callable bonds ở vùng yield thấp do upside bị call option chặn. Tránh áp kết luận option-free positive convexity lên embedded-option securities.","id":"S01-03","los_ids":["CFA26-06-13-LOS01"]},{"heading_vi":"Callable bond và negative convexity","body_vi":"Khi lãi suất giảm, issuer có động lực refinance debt bằng cách call bond, khiến giá bond khó tăng như straight bond. Khi benchmark yield cao, call ít có giá trị nên callable bond có thể gần như straight bond; khi yield thấp, effective convexity có thể chuyển âm và effective duration giảm.","id":"S01-04","los_ids":["CFA26-06-13-LOS01"]},{"heading_vi":"Putable bond và downside floor","body_vi":"Put option thuộc nhà đầu tư; khi lãi suất tăng mạnh, khả năng put bond ở mức giá hợp đồng giảm tác động rớt giá. Độ nhạy benchmark và convexity phụ thuộc vùng thực hiện quyền, quy định giá put, thời gian và issuer credit. Không kết luận tất cả putable bonds có duration bằng 0.","id":"S01-05","los_ids":["CFA26-06-13-LOS01"]},{"heading_vi":"Model assumptions & credit spreads","body_vi":"Effective metrics nhạy với prepayment model, call exercise rule, benchmark discount curve và OAS/credit spread assumption. Giữ OAS không đổi khi sốc benchmark để cô lập benchmark rate risk. Nếu benchmark thay đổi đồng thời credit spread, phải xét thêm spread risk thay vì gộp tất cả vào effective duration.","id":"S01-06","los_ids":["CFA26-06-13-LOS01"]},{"heading_vi":"Công thức và thời hạn cú sốc","body_vi":"V_minus là bond value khi benchmark curve giảm h, V_plus khi benchmark curve tăng h; effDur=(Vminus−Vplus)/(2V0h) và effConv=(Vminus+Vplus−2V0)/(V0h²). h=25bp viết 0.0025. Cú sốc giá trị nhỏ và đối xứng; rounding đầu vào làm tăng sai số.","id":"S01-07","los_ids":["CFA26-06-13-LOS01"]},{"heading_vi":"Phân biệt đo bằng own YTM và benchmark","body_vi":"Modified duration thay own YTM, cashflows giữ cố định; effective duration thay government benchmark curve, cashflows có thể thay đổi do quyền chọn. Cả hai định nghĩa về first-order price sensitivity nhưng không thể hoán đổi denominator hay interpretation khi market prices có embedded options.","id":"S01-08","los_ids":["CFA26-06-13-LOS01"]},{"heading_vi":"Công thức xấp xỉ theo benchmark","body_vi":"Với ∆curve annual benchmark yield dạng decimal, %∆P≈−EffDur×∆curve+0.5 EffConv×(∆curve)². Đây là benchmark curve shift, không mặc nhiên bằng shift riêng của own bond yield; credit spreads có thể chuyển động độc lập hoặc tương quan.","id":"S02-01","los_ids":["CFA26-06-13-LOS02"]},{"heading_vi":"Dấu duration và convexity","body_vi":"Với EffDur dương, benchmark rise dẫn đến first-order bond price decline. Nếu EffConv dương, adjustment là dương bất kể yield lên hay xuống. Nếu bond callable và EffConv âm, correction là âm, làm giảm upside yield decline và tăng estimated downside khi yield tăng.","id":"S02-02","los_ids":["CFA26-06-13-LOS02"]},{"heading_vi":"Tính USD change","body_vi":"Đầu tiên tính fractional price return, sau đó nhân market value của position. Hoặc MoneyEffDur=EffDur×V0 và MoneyEffConv=EffConv×V0 rồi dùng ∆V≈−MoneyEffDur∆curve+0.5 MoneyEffConv(∆curve)².","id":"S02-03","los_ids":["CFA26-06-13-LOS02"]},{"heading_vi":"Mốc nào dùng cho h","body_vi":"Khi từ mô hình có P_minus và P_plus, h dùng trong risk metrics phải bằng khoảng sốc mô hình. Khi tính giá cho kịch bản dự báo ∆curve có thể khác h; effective metrics chỉ là local approximation quanh trạng thái hiện tại. Không thay h bằng ∆curve trong công thức tính effective risk nếu pricing bump đã cho khác.","id":"S02-04","los_ids":["CFA26-06-13-LOS02"]},{"heading_vi":"Không luôn đúng với shock rất lớn","body_vi":"Dòng tiền có thể đổi đột ngột khi coupon reset, mortgage prepayment hoặc issuer exercise option; second-order expansion có thể sai với large yield shocks. Khi có thể, full option-adjusted model repricing cho kịch bản là chuẩn đối chiếu.","id":"S02-05","los_ids":["CFA26-06-13-LOS02"]},{"heading_vi":"Cùng dấu yield, khác cash flow","body_vi":"Trái phiếu không quyền chọn có C dương và price symmetry; callable có C âm tại vùng exercised. Hai bond cùng effDur chưa chắc có cùng %∆P: phải đưa cả convexity (và option regimes) vào tính.","id":"S02-06","los_ids":["CFA26-06-13-LOS02"]},{"heading_vi":"Bẫy units","body_vi":"Nếu EffDur=4.8, EffConv=28 và benchmark tăng 100bp, Δcurve=0.01. ∆P/P≈−4.8%+0.14%=−4.66%. Trường hợp benchmark giảm 100bp thì +4.8%+0.14%=+4.94%. Không gọi đây là thay đổi theo own YTM.","id":"S02-07","los_ids":["CFA26-06-13-LOS02"]},{"heading_vi":"Key rate duration là gì","body_vi":"Key rate duration (KRD) là price sensitivity với một benchmark tenor/key rate cụ thể, khi các key rates khác được giữ cố định theo phương pháp shock đã xác định và đường cong được nội suy. Ví dụ các key tenors 2y, 5y, 10y, 30y. Một duration duy nhất không thể diễn tả yield curve steepening, flattening hay twist.","id":"S03-01","los_ids":["CFA26-06-13-LOS03"]},{"heading_vi":"Key rate bump","body_vi":"Để tính KRD ở maturity k, shock benchmark rate tại node k lên/xuống h, giữ các nodes khác như quy ước, định giá lại trái phiếu và lấy KRD_k=(P_minus,k−P_plus,k)/(2P0h). Phải nêu rõ interpolation method giữa các key tenors.","id":"S03-02","los_ids":["CFA26-06-13-LOS03"]},{"heading_vi":"Risk contributions","body_vi":"Đối với small nonparallel shift: ∆P/P≈−Σ_k KRD_k∆r_k. Nếu 5y rate tăng còn 10y rate giảm thì hai contributions trái dấu. Với full parallel shift, Σ KRD_k thường xấp xỉ effective duration nếu key buckets và repricing method nhất quán.","id":"S03-03","los_ids":["CFA26-06-13-LOS03"]},{"heading_vi":"Portfolio key rate duration","body_vi":"KRD_port,k = Σ_i w_i KRD_i,k, với weights là market value. Báo cáo exposure theo tenor hữu ích cho hedging bằng futures/swaps tại kỳ hạn tương ứng và giám sát curve positioning. Cẩn thận với credit spread changes, FX và derivatives negative exposure.","id":"S03-04","los_ids":["CFA26-06-13-LOS03"]},{"heading_vi":"KRD khác maturity bucket","body_vi":"Một cash flow bond có duration dài có thể nhạy với nhiều nodes do interpolation; không bắt buộc chỉ có một tenor key. KRD dựa trên discounted cash flow contributions và curve construction, không đơn giản là principal maturity chia các buckets.","id":"S03-05","los_ids":["CFA26-06-13-LOS03"]},{"heading_vi":"Example steepening","body_vi":"Portfolio có KRD_5y=2.5 và KRD_10y=4.0. Nếu 5y +50bp, 10y −25bp, %∆P≈−2.5×.005−4×(−.0025)=−.0125+.01=−.0025=−0.25%. Parallel +50bp sẽ dự đoán −(2.5+4)×.005=−3.25%, khác xa.","id":"S03-06","los_ids":["CFA26-06-13-LOS03"]},{"heading_vi":"Giới hạn key rate durations","body_vi":"KRD là local derivative; nếu yield shifts lớn, curve construction, embedded option behavior và spread co-movements có thể thay đổi. KRD không trực tiếp dự đoán actual future price nếu credit rating migration, default hoặc illiquidity xảy ra.","id":"S03-07","los_ids":["CFA26-06-13-LOS03"]},{"heading_vi":"Analytical duration từ pricing model","body_vi":"Analytical duration được suy ra từ mô hình PV/cash flows hoặc mô hình OAS, giữ assumptions khác khi shock rates. Nó là độ nhạy mang tính cấu trúc theo benchmark rate riêng biệt và thường loại bỏ tác động spread đồng thời trừ khi được mô hình hóa tường minh.","id":"S04-01","los_ids":["CFA26-06-13-LOS04"]},{"heading_vi":"Empirical duration từ quan sát thị trường","body_vi":"Empirical duration là độ nhạy giá trái phiếu được ước lượng bằng thống kê thực nghiệm từ time series bond returns/prices và benchmark yield changes. Một phép regression đơn giản có hệ số của ∆benchmark: β≈−D_emp, nhưng lựa chọn mẫu, khung thời gian, controls và biến số khác quyết định chất lượng.","id":"S04-02","los_ids":["CFA26-06-13-LOS04"]},{"heading_vi":"Spread co-movement","body_vi":"Trong stress, Treasury yields có thể giảm như safe haven trong khi credit spreads tăng mạnh, gây bond high-yield price decline hoặc giảm ít hơn. Analytical duration với spread held constant dự đoán price increase; empirical duration từ observed data có thể nhỏ, gần 0, thậm chí âm.","id":"S04-03","los_ids":["CFA26-06-13-LOS04"]},{"heading_vi":"Độ ổn định của empirical estimates","body_vi":"Empirical duration nhạy với độ dài time window, nonlinearities, market illiquidity và regime changes. Quan sát một ngày không đủ để ước lượng thống kê ổn định; cần nhiều observations, cùng settlement convention và kiểm soát coupon/accrual changes.","id":"S04-04","los_ids":["CFA26-06-13-LOS04"]},{"heading_vi":"Khi nào ưu tiên loại nào","body_vi":"Analytical phù hợp valuation under specified scenarios và hedge design tách yield/spread; empirical hữu ích để đo historical realized co-movement và tactical risk behavior. Hai thước đo bổ sung chứ không thay thế nhau trong mọi trạng thái thị trường.","id":"S04-05","los_ids":["CFA26-06-13-LOS04"]},{"heading_vi":"Ví dụ sốc stress","body_vi":"Giả sử bond có benchmark duration4 và spread duration4. Benchmark giảm 50bp nhưng issuer spread giãn 90bp; giữ các yếu tố khác, ∆P/P≈−4(−.005)−4(.009)=+.02−.036=−1.6%. Dự báo chỉ theo benchmark sẽ là +2.0%, bỏ qua spread widening.","id":"S04-06","los_ids":["CFA26-06-13-LOS04"]},{"heading_vi":"Bẫy giá và yield","body_vi":"Regression hệ số của ∆price trên ∆yield khác hệ số của return fractional: phải chuẩn hóa giá mới ra duration. Empirical duration âm không có nghĩa straight bond đổi dấu derivative của own YTM; nó phản ánh joint movements của benchmark và spread.","id":"S04-07","los_ids":["CFA26-06-13-LOS04"]}],"formulae":[{"expression":"EffDur = [V(r−h)−V(r+h)]/(2V0 h)","variables":["r benchmark yield curve; h positive parallel shift as decimal; V0 full price with options model."],"assumptions":["Cash flows re-modeled after shock; OAS/credit spread held constant for isolated rate risk."],"id":"F01-01","los_ids":["CFA26-06-13-LOS01"]},{"expression":"EffConv = [V(r−h)+V(r+h)−2V0]/(V0 h²)","variables":["All values full-market prices from same valuation model."],"assumptions":["Same benchmark curve bump and scenario assumptions."],"id":"F01-02","los_ids":["CFA26-06-13-LOS01"]},{"expression":"ΔV/V0 ≈ −EffDur×Δcurve + 0.5×EffConv×(Δcurve)²","variables":["Δcurve annual benchmark rate decimal."],"assumptions":["Local Taylor expansion around current benchmark, option exercise endogenized."],"id":"F02-01","los_ids":["CFA26-06-13-LOS02"]},{"expression":"ΔV ≈ V0×[−EffDur×Δcurve+0.5×EffConv×(Δcurve)²]","variables":["V0 full market value."],"assumptions":["Same risk metrics and benchmark shock conventions."],"id":"F02-02","los_ids":["CFA26-06-13-LOS02"]},{"expression":"KRD_k = [P(k−h)−P(k+h)]/(2P0 h)","variables":["k key curve node, h benchmark node shock in decimals."],"assumptions":["Other key tenors fixed under chosen interpolation method."],"id":"F03-01","los_ids":["CFA26-06-13-LOS03"]},{"expression":"ΔP/P ≈ −Σ_k KRD_k × Δr_k","variables":["KRD_k yearly sensitivity at each key maturity."],"assumptions":["Small independent key rate shifts; omit convexity/credit spread change."],"id":"F03-02","los_ids":["CFA26-06-13-LOS03"]},{"expression":"KRD_port,k ≈ Σ_i w_i KRD_i,k","variables":["Market value weights w_i."],"assumptions":["Consistent benchmark curve and key rate grid."],"id":"F03-03","los_ids":["CFA26-06-13-LOS03"]},{"expression":"ΔP/P ≈ α − D_emp×Δbenchmark + ε","variables":["β regression slope = −D_emp when no other controls."],"assumptions":["Historical observations; single simple regression only."],"id":"F04-01","los_ids":["CFA26-06-13-LOS04"]},{"expression":"ΔP/P ≈ −D_benchmark×Δr_benchmark − D_spread×Δspread","variables":["Benchmark and spread duration may differ."],"assumptions":["Local price response, linear approximation; ignore convexity."],"id":"F04-02","los_ids":["CFA26-06-13-LOS04"]}],"worked_examples":[{"problem":"Mô hình quyền chọn cho V0=100, V_minus=100.502, V_plus=99.502 tại benchmark ±10bp. Tính risk metrics.","solution_steps":["h=0.001; EffDur=(100.502−99.502)/(2×100×0.001)=5.","EffConv=(100.502+99.502−200)/(100×0.001²)=40.","Đây là effective metrics theo benchmark curve, không phải own-YTM derivative."],"answer":"EffDur=5; EffConv=40 theo annual benchmark yield.","id":"E01-01","los_ids":["CFA26-06-13-LOS01"]},{"problem":"Một callable bond phản ứng giá như thế nào nếu yield giảm và call gần chắc chắn?","solution_steps":["Issuer sẽ có lợi ích tái cấp vốn khi yield hạ.","Upside giá bị hạn chế do khả năng nhận call price sớm.","Mô hình điều chỉnh exercise probabilities sau yield shock, có thể cho effective convexity âm."],"answer":"Không dùng fixed cashflow modified duration để thay thế effective risk measures.","id":"E01-02","los_ids":["CFA26-06-13-LOS01"]},{"problem":"EffDur=4.8, EffConv=28, government benchmark curve tăng 100bp. Ước tính biến động giá.","solution_steps":["Δcurve=0.01; duration effect=−4.8×0.01=−4.80%.","Convexity effect=0.5×28×(.01)²=+0.14%.","Net≈−4.66%."],"answer":"−4.66% for benchmark +100bp, assuming option-adjusted measures locally applicable.","id":"E02-01","los_ids":["CFA26-06-13-LOS02"]},{"problem":"Bond 2 triệu USD với EffDur=4.8, EffConv=−20, benchmark giảm 50bp. ∆V?","solution_steps":["∆curve=−.005; duration=−4.8×(−.005)=+.024.","Convexity=.5×(−20)×(.005)²=−.00025.","Total=+.02375=+2.375%; ∆V=2,000,000×.02375=47,500 USD."],"answer":"Giá trị tăng khoảng USD47,500; negative convexity làm upside thấp hơn dự đoán duration-only.","id":"E02-02","los_ids":["CFA26-06-13-LOS02"]},{"problem":"Danh mục KRD_5y=2.5, KRD_10y=4; yield 5y +50bp, 10y −25bp. Tính %∆V.","solution_steps":["5y: −2.5×.005=−1.25%.","10y: −4×(−.0025)=+1.00%.","Net −0.25%, không dùng parallel shift +50bp cho cả đường."],"answer":"Portfolio giảm khoảng 0.25% trước convexity và spread changes.","id":"E03-01","los_ids":["CFA26-06-13-LOS03"]},{"problem":"Trái phiếu có P0=100, shock 5y key node ±10bp cho P_minus=100.30, P_plus=99.70. Tính KRD5.","solution_steps":["h=.001; P_minus−P_plus=.60.","KRD5=.60/(2×100×.001)=3.","Nếu các KRD khác cộng 2, tổng KRD khoảng 5 cho parallel shift."],"answer":"KRD5=3.0 năm-equivalent risk sensitivity.","id":"E03-02","los_ids":["CFA26-06-13-LOS03"]},{"problem":"High-yield bond: benchmark duration4, spread duration4; Treasury −50bp, credit spread +90bp. Estimated return?","solution_steps":["Benchmark price effect=−4×(−.005)=+2.0%.","Spread price effect=−4×(.009)=−3.6%.","Net≈−1.6%, dù risk-free rate giảm."],"answer":"Approximate return −1.6% before coupon/carry.","id":"E04-01","los_ids":["CFA26-06-13-LOS04"]},{"problem":"Một regressions dùng bond return r≈0.002−3.2∆benchmark. Empirical duration suy ra?","solution_steps":["Hệ số của benchmark yield change β=−3.2.","Nếu return đơn vị decimal và yield change decimal, D_emp=−β=3.2.","Đây là observed empirical exposure trong window của regression, không chắc là analytical duration."],"answer":"Empirical duration≈3.2 trong mẫu, không phải guarantee cho tương lai.","id":"E04-02","los_ids":["CFA26-06-13-LOS04"]}],"questions":[{"stem":"Loại trái phiếu nào cần effective duration nhất?","options":["Straight annual coupon bond","Callable với dòng tiền thay đổi theo quyền gọi","Zero-coupon default-free"],"correct_option":1,"explanation":"Issuer call behavior thay đổi theo benchmark yields, vì thế phải định giá lại cash flows khi đo rủi ro.","id":"Q01-01","los_ids":["CFA26-06-13-LOS01"]},{"stem":"V0=100, V_minus=100.502, V_plus=99.502, h=10bp; EffDur?","options":["4","10","5"],"correct_option":2,"explanation":"EffDur=1/(2×100×0.001)=5; cú sốc benchmark 10bp bằng 0.001, không phải 0.01.","id":"Q01-02","los_ids":["CFA26-06-13-LOS01"]},{"stem":"Callable bond ở vùng benchmark yield rất thấp có thể có convexity nào?","options":["Negative effective convexity","Luôn strictly positive convexity","Convexity chắc chắn bằng maturity"],"correct_option":0,"explanation":"Expected exercise giới hạn giá lên khi rates giảm; effective convexity có thể âm trong vùng call-in-the-money.","id":"Q01-03","los_ids":["CFA26-06-13-LOS01"]},{"stem":"EffDur=4.8, EffConv=28, benchmark +100bp; ∆P/P?","options":["+4.94%","−4.66%","−4.94%"],"correct_option":1,"explanation":"Duration term −4.80% cộng adjustment +0.14% khi benchmark tăng 100bp, nên còn −4.66%.","id":"Q02-01","los_ids":["CFA26-06-13-LOS02"]},{"stem":"EffDur=4.8, EffConv=−20, benchmark −50bp. %∆P?","options":["+2.425%","−2.375%","+2.375%"],"correct_option":2,"explanation":"Duration term +2.4%; convexity correction −0.025%, tổng +2.375% do effective convexity âm.","id":"Q02-02","los_ids":["CFA26-06-13-LOS02"]},{"stem":"Risk metrics đo từ bump ±25bp nhưng forecast curve move +100bp; dùng sốc nào trong công thức dự báo?","options":["+0.01","+0.0025","+1.00"],"correct_option":0,"explanation":"h=0.0025 dùng để ước lượng duration/convexity từ prices; shock dự báo là Δcurve=0.01.","id":"Q02-03","los_ids":["CFA26-06-13-LOS02"]},{"stem":"Các kỳ hạn benchmark 5y +50bp, 10y −25bp và KRD lần lượt 2.5,4.0; return approximation?","options":["+3.25%","−0.25%","−3.25%"],"correct_option":1,"explanation":"−2.5×.005−4×(−.0025)=−.0025=−0.25%; không phải parallel rate shift.","id":"Q03-01","los_ids":["CFA26-06-13-LOS03"]},{"stem":"Key rate durations đặc biệt có ích khi?","options":["Tất cả benchmark tenors tăng cùng rate","Trái phiếu không có coupon","Yield curve nonparallel shift"],"correct_option":2,"explanation":"KRD phân tách độ nhạy theo tenors, giúp đánh giá steepening và flattening mà một duration không mô tả.","id":"Q03-02","los_ids":["CFA26-06-13-LOS03"]},{"stem":"Nếu các key tenors đồng loạt dịch cùng 1bp, tổng KRD thường gần?","options":["Effective duration","Convexity","Probability of default"],"correct_option":0,"explanation":"Sum các sensitivities theo từng node thường xấp xỉ effective duration với parallel shift và cùng construction assumptions.","id":"Q03-03","los_ids":["CFA26-06-13-LOS03"]},{"stem":"Thước đo nào được ước lượng từ lịch sử giá và yield quan sát?","options":["Macaulay maturity","Empirical duration","Analytical duration"],"correct_option":1,"explanation":"Empirical duration dùng regression/thống kê historical co-movements chứ không chỉ derivatives của mô hình PV.","id":"Q04-01","los_ids":["CFA26-06-13-LOS04"]},{"stem":"Treasury yield giảm trong khủng hoảng, credit spreads tăng; risk nào bị analytical benchmark duration bỏ sót?","options":["Coupon frequency","Par value","Spread co-movement"],"correct_option":2,"explanation":"Nếu credit spread cùng dịch khi benchmark yield shock, analytical model giữ spread không đổi sẽ bỏ qua tác động lớn đó.","id":"Q04-02","los_ids":["CFA26-06-13-LOS04"]},{"stem":"Regression return = α−3.2∆benchmark; empirical duration là?","options":["3.2","−3.2","0.32"],"correct_option":0,"explanation":"Hệ số của yield change là −D_emp, do đó D_emp=3.2 khi return và rate cùng đơn vị decimal.","id":"Q04-03","los_ids":["CFA26-06-13-LOS04"]}],"flashcards":[{"front":"Tại sao yield duration không đủ — trình bày bản chất và công thức?","back":"Yield-based modified duration và convexity giả định các cash flows dự kiến không đổi khi tăng hoặc giảm own YTM. Trái phiếu callable, putable hoặc MBS có embedded options tạo ra uncertainty vì dòng tiền có thể biến đổi theo lãi suất. Do đó chỉ chiết khấu lại một bộ cash flows cố định sẽ đánh giá sai cả chiều và mức độ rủi ro.","id":"C01-01","los_ids":["CFA26-06-13-LOS01"]},{"front":"Effective duration — trình bày bản chất và công thức?","back":"Effective duration đo độ nhạy full price khi benchmark yield curve dịch chuyển một lượng nhỏ, trong khi cash-flow model được định giá lại có tính đến việc nhà phát hành/người vay thay đổi hành vi theo lãi suất. Công thức dùng V_minus, V_plus từ mô hình pricing, không nhất thiết giống modified duration theo YTM.","id":"C01-02","los_ids":["CFA26-06-13-LOS01"]},{"front":"Effective convexity — trình bày bản chất và công thức?","back":"Effective convexity dùng sai phân bậc hai đối với benchmark curve shock, vẫn dùng P0 làm cơ sở và ∆curve². Nó có thể âm với callable bonds ở vùng yield thấp do upside bị call option chặn. Tránh áp kết luận option-free positive convexity lên embedded-option securities.","id":"C01-03","los_ids":["CFA26-06-13-LOS01"]},{"front":"Callable bond và negative convexity — trình bày bản chất và công thức?","back":"Khi lãi suất giảm, issuer có động lực refinance debt bằng cách call bond, khiến giá bond khó tăng như straight bond. Khi benchmark yield cao, call ít có giá trị nên callable bond có thể gần như straight bond; khi yield thấp, effective convexity có thể chuyển âm và effective duration giảm.","id":"C01-04","los_ids":["CFA26-06-13-LOS01"]},{"front":"Công thức xấp xỉ theo benchmark — trình bày bản chất và công thức?","back":"Với ∆curve annual benchmark yield dạng decimal, %∆P≈−EffDur×∆curve+0.5 EffConv×(∆curve)². Đây là benchmark curve shift, không mặc nhiên bằng shift riêng của own bond yield; credit spreads có thể chuyển động độc lập hoặc tương quan.","id":"C02-01","los_ids":["CFA26-06-13-LOS02"]},{"front":"Dấu duration và convexity — trình bày bản chất và công thức?","back":"Với EffDur dương, benchmark rise dẫn đến first-order bond price decline. Nếu EffConv dương, adjustment là dương bất kể yield lên hay xuống. Nếu bond callable và EffConv âm, correction là âm, làm giảm upside yield decline và tăng estimated downside khi yield tăng.","id":"C02-02","los_ids":["CFA26-06-13-LOS02"]},{"front":"Tính USD change — trình bày bản chất và công thức?","back":"Đầu tiên tính fractional price return, sau đó nhân market value của position. Hoặc MoneyEffDur=EffDur×V0 và MoneyEffConv=EffConv×V0 rồi dùng ∆V≈−MoneyEffDur∆curve+0.5 MoneyEffConv(∆curve)².","id":"C02-03","los_ids":["CFA26-06-13-LOS02"]},{"front":"Mốc nào dùng cho h — trình bày bản chất và công thức?","back":"Khi từ mô hình có P_minus và P_plus, h dùng trong risk metrics phải bằng khoảng sốc mô hình. Khi tính giá cho kịch bản dự báo ∆curve có thể khác h; effective metrics chỉ là local approximation quanh trạng thái hiện tại. Không thay h bằng ∆curve trong công thức tính effective risk nếu pricing bump đã cho khác.","id":"C02-04","los_ids":["CFA26-06-13-LOS02"]},{"front":"Key rate duration là gì — trình bày bản chất và công thức?","back":"Key rate duration (KRD) là price sensitivity với một benchmark tenor/key rate cụ thể, khi các key rates khác được giữ cố định theo phương pháp shock đã xác định và đường cong được nội suy. Ví dụ các key tenors 2y, 5y, 10y, 30y. Một duration duy nhất không thể diễn tả yield curve steepening, flattening hay twist.","id":"C03-01","los_ids":["CFA26-06-13-LOS03"]},{"front":"Key rate bump — trình bày bản chất và công thức?","back":"Để tính KRD ở maturity k, shock benchmark rate tại node k lên/xuống h, giữ các nodes khác như quy ước, định giá lại trái phiếu và lấy KRD_k=(P_minus,k−P_plus,k)/(2P0h). Phải nêu rõ interpolation method giữa các key tenors.","id":"C03-02","los_ids":["CFA26-06-13-LOS03"]},{"front":"Risk contributions — trình bày bản chất và công thức?","back":"Đối với small nonparallel shift: ∆P/P≈−Σ_k KRD_k∆r_k. Nếu 5y rate tăng còn 10y rate giảm thì hai contributions trái dấu. Với full parallel shift, Σ KRD_k thường xấp xỉ effective duration nếu key buckets và repricing method nhất quán.","id":"C03-03","los_ids":["CFA26-06-13-LOS03"]},{"front":"Portfolio key rate duration — trình bày bản chất và công thức?","back":"KRD_port,k = Σ_i w_i KRD_i,k, với weights là market value. Báo cáo exposure theo tenor hữu ích cho hedging bằng futures/swaps tại kỳ hạn tương ứng và giám sát curve positioning. Cẩn thận với credit spread changes, FX và derivatives negative exposure.","id":"C03-04","los_ids":["CFA26-06-13-LOS03"]},{"front":"Analytical duration từ pricing model — trình bày bản chất và công thức?","back":"Analytical duration được suy ra từ mô hình PV/cash flows hoặc mô hình OAS, giữ assumptions khác khi shock rates. Nó là độ nhạy mang tính cấu trúc theo benchmark rate riêng biệt và thường loại bỏ tác động spread đồng thời trừ khi được mô hình hóa tường minh.","id":"C04-01","los_ids":["CFA26-06-13-LOS04"]},{"front":"Empirical duration từ quan sát thị trường — trình bày bản chất và công thức?","back":"Empirical duration là độ nhạy giá trái phiếu được ước lượng bằng thống kê thực nghiệm từ time series bond returns/prices và benchmark yield changes. Một phép regression đơn giản có hệ số của ∆benchmark: β≈−D_emp, nhưng lựa chọn mẫu, khung thời gian, controls và biến số khác quyết định chất lượng.","id":"C04-02","los_ids":["CFA26-06-13-LOS04"]},{"front":"Spread co-movement — trình bày bản chất và công thức?","back":"Trong stress, Treasury yields có thể giảm như safe haven trong khi credit spreads tăng mạnh, gây bond high-yield price decline hoặc giảm ít hơn. Analytical duration với spread held constant dự đoán price increase; empirical duration từ observed data có thể nhỏ, gần 0, thậm chí âm.","id":"C04-03","los_ids":["CFA26-06-13-LOS04"]},{"front":"Độ ổn định của empirical estimates — trình bày bản chất và công thức?","back":"Empirical duration nhạy với độ dài time window, nonlinearities, market illiquidity và regime changes. Quan sát một ngày không đủ để ước lượng thống kê ổn định; cần nhiều observations, cùng settlement convention và kiểm soát coupon/accrual changes.","id":"C04-04","los_ids":["CFA26-06-13-LOS04"]}],"review_status":"targeted_CFAI_Kaplan_SAPP_math_and_browser_QA_not_exhaustive_full_PDF_verification"},{"module_id":"CFA26-06-14","title":"Credit Risk","version":"2026","source_basis":[{"source_id":"CFAI","pdf_pages":[355,392],"relation":"primary"},{"source_id":"Kaplan","pdf_pages":[118,128],"relation":"supplementary"},{"source_id":"SAPP","pdf_pages":[389,420],"relation":"supplementary"}],"los_coverage":[{"los_id":"CFA26-06-14-LOS01","status":"targeted_three_source_and_independent_math_QA_pass","learning_goal_vi":"Mô tả rủi ro tín dụng và các thành phần probability of default và loss given default.","competency_criteria":["Bám sát LOS CFA Institute 2026","Đối chiếu Kaplan và SAPP theo trang nguồn","Có ví dụ áp dụng và lỗi thường gặp","Có câu hỏi với giải thích đáp án","Kiểm tra phép tính độc lập và tính toàn vẹn website"],"concept_ids":["S01-01","S01-02","S01-03","S01-04","S01-05","S01-06","S01-07","S01-08"],"formula_ids":["F01-01","F01-02","F01-03"],"example_ids":["E01-01","E01-02"],"question_ids":["Q01-01","Q01-02","Q01-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V6_FI_ONLINE.pdf","pdf_page":363},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book3.pdf","pdf_page":118},"SAPP_2026":{"file":"SAPP Fixed Income.pdf","pdf_page":402}},"missing_items":[]},{"los_id":"CFA26-06-14-LOS02","status":"targeted_three_source_and_independent_math_QA_pass","learning_goal_vi":"Mô tả ứng dụng của credit ratings và giới hạn của các đánh giá xếp hạng.","competency_criteria":["Bám sát LOS CFA Institute 2026","Đối chiếu Kaplan và SAPP theo trang nguồn","Có ví dụ áp dụng và lỗi thường gặp","Có câu hỏi với giải thích đáp án","Kiểm tra phép tính độc lập và tính toàn vẹn website"],"concept_ids":["S02-01","S02-02","S02-03","S02-04","S02-05","S02-06","S02-07"],"formula_ids":["F02-01"],"example_ids":["E02-01","E02-02"],"question_ids":["Q02-01","Q02-02","Q02-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V6_FI_ONLINE.pdf","pdf_page":370},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book3.pdf","pdf_page":121},"SAPP_2026":{"file":"SAPP Fixed Income.pdf","pdf_page":410}},"missing_items":[]},{"los_id":"CFA26-06-14-LOS03","status":"targeted_three_source_and_independent_math_QA_pass","learning_goal_vi":"Mô tả yếu tố vĩ mô, thị trường và riêng issuer ảnh hưởng mức độ và biến động yield spreads.","competency_criteria":["Bám sát LOS CFA Institute 2026","Đối chiếu Kaplan và SAPP theo trang nguồn","Có ví dụ áp dụng và lỗi thường gặp","Có câu hỏi với giải thích đáp án","Kiểm tra phép tính độc lập và tính toàn vẹn website"],"concept_ids":["S03-01","S03-02","S03-03","S03-04","S03-05","S03-06","S03-07","S03-08"],"formula_ids":["F03-01","F03-02","F03-03"],"example_ids":["E03-01","E03-02"],"question_ids":["Q03-01","Q03-02","Q03-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V6_FI_ONLINE.pdf","pdf_page":377},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book3.pdf","pdf_page":123},"SAPP_2026":{"file":"SAPP Fixed Income.pdf","pdf_page":413}},"missing_items":[]}],"sections":[{"heading_vi":"Credit risk và nguồn trả nợ","body_vi":"Credit risk là khả năng người vay không thực hiện đầy đủ các nghĩa vụ thanh toán hoặc làm nhà đầu tư chịu lỗ do creditworthiness giảm. Giá trái phiếu chịu cả default risk và spread widening trước default; expected loss chỉ là một thành phần của yêu cầu lợi tức. Xem dòng tiền hoạt động, tài sản bảo đảm và nguồn refinancing.","id":"S01-01","los_ids":["CFA26-06-14-LOS01"]},{"heading_vi":"Probability of default (POD/PD)","body_vi":"PD đo xác suất xảy ra sự kiện vỡ nợ trong một horizon xác định như 1 năm. Cần gắn definition of default, horizon, entity/issue, scenario và conditional/unconditional PD rõ ràng. Không đồng nhất PD với tỷ lệ mất toàn bộ giá trị.","id":"S01-02","los_ids":["CFA26-06-14-LOS01"]},{"heading_vi":"Loss given default (LGD)","body_vi":"LGD là tỷ lệ tổn thất có điều kiện đã xảy ra default; recovery rate RR≈1−LGD trong mô hình đơn giản. Tài sản bảo đảm, seniority, collateral value, thời gian thu hồi và costs ảnh hưởng LGD. Một issuer có PD cao nhưng khoản nợ có bảo đảm vẫn có thể LGD thấp.","id":"S01-03","los_ids":["CFA26-06-14-LOS01"]},{"heading_vi":"Exposure at default (EAD)","body_vi":"EAD là giá trị tiếp xúc dự kiến tại thời điểm default. Trái phiếu thường liên quan principal outstanding, accrued interest và recovery timing; revolving credit cần xét unused commitment drawdown. Không luôn dùng face 100 khi position mua discount hoặc có amortization.","id":"S01-04","los_ids":["CFA26-06-14-LOS01"]},{"heading_vi":"Expected loss","body_vi":"Dưới một horizon, expected loss dollar≈PD×LGD×EAD, khi các tham số được định nghĩa tương thích và assumed independence/conditional estimate phù hợp. Mô hình credit spread ≈PD×LGD chỉ là approximation cho low-risk short horizon, bỏ qua risk premia, liquidity, term structure và risk-free compounding.","id":"S01-05","los_ids":["CFA26-06-14-LOS01"]},{"heading_vi":"5 Cs / bottom-up analysis","body_vi":"Capacity: cash flow debt service; capital: equity cushion/leverage; collateral: recovery sources; covenants: creditor protections; character: governance/payment behavior; conditions: industry/macroeconomic landscape. Sử dụng combined qualitative and quantitative approach, không áp dụng máy móc một ratio.","id":"S01-06","los_ids":["CFA26-06-14-LOS01"]},{"heading_vi":"Top-down vs bottom-up","body_vi":"Top-down xem GDP, policy rates, inflation, refinancing conditions và sector stress; bottom-up xem profitability, leverage, coverage, debt maturities, covenants, cash flows. Credit spreads phản ánh cả hai; một rating không thể thay thế việc đánh giá theo issuer và issue.","id":"S01-07","los_ids":["CFA26-06-14-LOS01"]},{"heading_vi":"PD khác rating migration risk","body_vi":"Issuer chưa default nhưng rating bị downgrade có thể khiến required spread widen và price giảm. Loss at default không phải duy nhất hình thức credit loss; credit spread volatility quan trọng cho investment grade holdings.","id":"S01-08","los_ids":["CFA26-06-14-LOS01"]},{"heading_vi":"Issuer rating và issue rating","body_vi":"Issuer rating phản ánh opinion về overall obligor creditworthiness; issue rating đánh giá khoản phát hành cụ thể, có thể chịu ảnh hưởng của security, priority of claims và guarantee. Không tự đồng nhất rating mọi issue với rating issuer. Trái phiếu secured/senior có recovery khác unsecured/subordinated.","id":"S02-01","los_ids":["CFA26-06-14-LOS02"]},{"heading_vi":"Credit rating là opinion, không phải bảo lãnh","body_vi":"Rating thể hiện ý kiến phân loại relative credit risk dựa trên thông tin và methodology, không cam kết repayment, không phải trực tiếp investment recommendation hay exact expected loss number. Investor vẫn cần phân tích độc lập và xem suitability/liquidity.","id":"S02-02","los_ids":["CFA26-06-14-LOS02"]},{"heading_vi":"Rating scales và ngưỡng IG","body_vi":"Các thang S&P/Fitch và Moody’s có ký hiệu khác nhau. Investment grade thường BBB−/Baa3 trở lên; BB+/Ba1 trở xuống thuộc speculative/high yield. Cần hiểu watchlist/outlook và transition risk, không coi một notch movement là deterministic spread change.","id":"S02-03","los_ids":["CFA26-06-14-LOS02"]},{"heading_vi":"Ứng dụng trong quản lý danh mục","body_vi":"Ratings giúp định nghĩa eligible assets theo IPS, hạn chế exposure, định giá tương đối, giao dịch theo credit buckets và giám sát downgrade risk. Các portfolio mandates có giới hạn minimum rating hoặc cách tính composite ratings khi agencies disagree.","id":"S02-04","los_ids":["CFA26-06-14-LOS02"]},{"heading_vi":"Rating lag và market spreads","body_vi":"Các ratings không liên tục điều chỉnh mỗi ngày; credit spreads thay đổi theo market perception, risk appetite và liquidity nhanh hơn. Rating downgrade thường theo sau sự xấu đi fundamentals hoặc market signals; không đợi downgrade mới quản lý risk.","id":"S02-05","los_ids":["CFA26-06-14-LOS02"]},{"heading_vi":"Rủi ro phương pháp và xung đột lợi ích","body_vi":"Issuer-pays model có conflict of interest; dữ liệu kế toán có thể thiếu, ratings có model uncertainty, cyclicality và calibration assumptions. Credit opinions của sovereign cũng phụ thuộc khả năng hỗ trợ, chính sách và institutional risks.","id":"S02-06","los_ids":["CFA26-06-14-LOS02"]},{"heading_vi":"Thận trọng khi so rating liên ngành","body_vi":"Cùng notch không bảo đảm giống nhau về recovery và price volatility, đặc biệt khi sector/country khác nhau. Issue rating không capture FX liquidity, basis, collateral liquidation uncertainty và specific investor mandate.","id":"S02-07","los_ids":["CFA26-06-14-LOS02"]},{"heading_vi":"Credit spread là gì","body_vi":"Yield spread là khoảng cách giữa yield của bond risky và reference benchmark cùng tenor/curve convention. Spread phản ánh expected default loss, uncertainty/risk premium, market liquidity, taxes và supply-demand; không đồng nghĩa hoàn toàn actuarial expected loss. Cần cùng currency, duration và benchmark khi so sánh.","id":"S03-01","los_ids":["CFA26-06-14-LOS03"]},{"heading_vi":"Business cycle","body_vi":"Khi GDP tăng trưởng, lợi nhuận và cash flows cải thiện, PD có thể giảm và spreads co hẹp; suy thoái làm khả năng trả nợ suy yếu và spreads giãn. High-yield thường nhạy với chu kỳ và equities hơn, investment grade có thể chịu ảnh hưởng rates nhiều hơn.","id":"S03-02","los_ids":["CFA26-06-14-LOS03"]},{"heading_vi":"Risk aversion và flight to quality","body_vi":"Trong stress, investors mua government bonds làm benchmark yields giảm đồng thời yêu cầu credit premium tăng. Vì vậy corporate spread có thể giãn trong khi benchmark giảm; quan hệ đồng biến của risky total yields với Treasury không phải luôn đúng.","id":"S03-03","los_ids":["CFA26-06-14-LOS03"]},{"heading_vi":"Liquidity và market microstructure","body_vi":"Issue size, trading frequency, market maker balance sheet, bid-ask spread, funding costs và dealer inventories ảnh hưởng liquidity premium. Cùng issuer rating và maturity, bond ít giao dịch thường spread cao hơn vì selling pressure/liquidation costs.","id":"S03-04","los_ids":["CFA26-06-14-LOS03"]},{"heading_vi":"Issuer specific fundamentals","body_vi":"Profit margins, interest coverage, leverage, maturity ladder, cash buffers, asset quality, covenant headroom và management credibility làm spread thay đổi. Negative earnings surprise và refinancing wall có thể widening trước formal downgrade.","id":"S03-05","los_ids":["CFA26-06-14-LOS03"]},{"heading_vi":"Seniority, collateral, issue terms","body_vi":"Issue secured senior debt có LGD thấp hơn junior subordinated debt nếu collateral thực thi được; covenants cũng ảnh hưởng downside. Bond có call feature hoặc unusual tax treatment phải phân biệt spread do embedded optionality với spread do credit risk.","id":"S03-06","los_ids":["CFA26-06-14-LOS03"]},{"heading_vi":"Giá biến động khi spread thay đổi","body_vi":"Với benchmark không đổi, ∆P/P≈−SpreadDur×∆spread, xấp xỉ bậc nhất; theo cách giản lược curriculum có thể dùng yield duration nếu total yield shifts do spread. Với large spread changes hoặc options, cần convexity và scenario repricing; không áp spread duration bằng 0.","id":"S03-07","los_ids":["CFA26-06-14-LOS03"]},{"heading_vi":"Yield spread units","body_vi":"Corporate y=5.8%, matched Treasury y=3.5% => spread=2.3%=230bp. Nếu spread từ 230bp lên 280bp thì ∆spread=50bp=.005; bond spread duration5 có xấp xỉ price drop 2.5% (trước convexity), không phải 25%.","id":"S03-08","los_ids":["CFA26-06-14-LOS03"]}],"formulae":[{"expression":"Expected Loss (currency) ≈ POD × LGD × EAD","variables":["POD probability over chosen horizon, LGD conditional loss proportion, EAD exposure."],"assumptions":["Simplified one-period expected loss, consistently conditional estimates."],"id":"F01-01","los_ids":["CFA26-06-14-LOS01"]},{"expression":"LGD ≈ 1 − Recovery Rate","variables":["Recovery proceeds as fraction of exposure including settlement conventions."],"assumptions":["Recovery measured same denominator, net of costs if required."],"id":"F01-02","los_ids":["CFA26-06-14-LOS01"]},{"expression":"EL rate ≈ POD × LGD","variables":["Divide currency EL by EAD."],"assumptions":["Same horizon and consistent exposure assumptions; not market spread exactly."],"id":"F01-03","los_ids":["CFA26-06-14-LOS01"]},{"expression":"Rating risk ≠ PD exactly ≠ expected loss ≠ credit spread","variables":["Rating is ordinal opinion; each quantitative measure needs own horizon and assumptions."],"assumptions":["Use qualitative distinction rather than numerical conversion absent a calibration table."],"id":"F02-01","los_ids":["CFA26-06-14-LOS02"]},{"expression":"Yield spread (bp) = [yield_risky − yield_reference]×10,000","variables":["Yields as decimals; match tenor, currency and discount convention."],"assumptions":["Simple nominal yield difference, not full OAS calculation."],"id":"F03-01","los_ids":["CFA26-06-14-LOS03"]},{"expression":"ΔP/P ≈ −SpreadDur×Δspread","variables":["SpreadDur annual sensitivity; Δspread decimal."],"assumptions":["Small instantaneous spread move, benchmark unchanged, fixed cashflows."],"id":"F03-02","los_ids":["CFA26-06-14-LOS03"]},{"expression":"Total yield change ≈ Δbenchmark + Δspread","variables":["Par/spot benchmarks and credit spread must be comparably defined."],"assumptions":["Linear additive yield decomposition under simplified framework."],"id":"F03-03","los_ids":["CFA26-06-14-LOS03"]}],"worked_examples":[{"problem":"Một bond exposure 10 triệu USD, annual PD=2%, expected recovery=60%. Annual expected loss?","solution_steps":["LGD=1−0.60=40%.","EL=10,000,000×0.02×0.40=USD80,000.","EL/EAD=0.008=0.8%=80bp, không mặc nhiên bằng observed credit spread."],"answer":"Expected loss USD80,000 / 1 năm (80bp exposure), under simplified horizon assumptions.","id":"E01-01","los_ids":["CFA26-06-14-LOS01"]},{"problem":"Khoản nợ secured có PD4%, recovery75%, EAD2 triệu. Expected loss?","solution_steps":["LGD=1−.75=.25.","EL=.04×.25×2,000,000=20,000 USD.","Bảo đảm cao giúp LGD thấp, nhưng không làm PD tự động giảm."],"answer":"Expected loss USD20,000; LGD 25%.","id":"E01-02","los_ids":["CFA26-06-14-LOS01"]},{"problem":"Một borrower được chấm BBB− bởi S&P, Baa3 bởi Moody’s. Phân loại chung?","solution_steps":["Đây là mức thấp nhất trong IG theo hai agency rating scales.","Không coi nó là AAA hoặc không có credit risk.","Issue-specific subordination có thể làm rating issue thấp hơn issuer rating."],"answer":"BBB−/Baa3 thông thường vẫn thuộc investment grade, nhưng rủi ro không phải bằng 0.","id":"E02-01","los_ids":["CFA26-06-14-LOS02"]},{"problem":"Trái phiếu corporate chưa bị downgrade nhưng spread từ 150bp tăng 250bp. Có thể xảy ra?","solution_steps":["Credit spreads là market price và chịu liquidity/risk appetite changes liên tục.","Ratings là periodic opinions nên có thể phản ứng chậm.","Investor có thể chịu mark-to-market loss dù rating chưa thay đổi."],"answer":"Có; rating stability không đảm bảo stable bond price.","id":"E02-02","los_ids":["CFA26-06-14-LOS02"]},{"problem":"Corporate YTM5.8%, comparable Treasury3.5%. Spread? Nếu giãn 50bp và SpreadDur=5, giá thay đổi?","solution_steps":["Initial spread=.058−.035=.023=230bp.","New spread=280bp; Δspread=.005.","Price effect≈−5×.005=−.025=−2.5%, nếu benchmark không đổi."],"answer":"Credit spread 230bp ban đầu; giá giảm khoảng 2.5% khi spread widen 50bp.","id":"E03-01","los_ids":["CFA26-06-14-LOS03"]},{"problem":"Issuer bị downgrade outlook và market makers giảm inventory. Điều gì có thể xảy ra với spread?","solution_steps":["Issuer fundamental stress làm market yêu cầu higher credit risk premium.","Dealer balance sheet contraction làm liquidity premium tăng.","Hai yếu tố có thể cùng widening spread dù risk-free rate đứng yên."],"answer":"Credit spread có thể tăng do cả issuer-specific risk và liquidity risk.","id":"E03-02","los_ids":["CFA26-06-14-LOS03"]}],"questions":[{"stem":"PD=2%, LGD=40%, EAD10m. EL bằng?","options":["USD800,000","USD200,000","USD80,000"],"correct_option":2,"explanation":"EL=.02×.4×10,000,000=80,000 USD, tức 80bp EAD theo năm trong giả định đơn giản.","id":"Q01-01","los_ids":["CFA26-06-14-LOS01"]},{"stem":"Recovery 75% thì LGD theo mô hình đơn giản?","options":["25%","75%","100%"],"correct_option":0,"explanation":"LGD=1−Recovery Rate=25%; phải dùng cùng mẫu số EAD và xét collection costs nếu có.","id":"Q01-02","los_ids":["CFA26-06-14-LOS01"]},{"stem":"Issuer downgrade nhưng không default có thể làm?","options":["LGD luôn bằng 100%","Required yield spread tăng, bond price giảm","Không ảnh hưởng giá"],"correct_option":1,"explanation":"Credit migration và spread repricing có thể gây mark-to-market loss trước khi borrower defaults.","id":"Q01-03","los_ids":["CFA26-06-14-LOS01"]},{"stem":"Cấp xếp hạng nào là ngưỡng thấp nhất của investment grade theo S&P?","options":["BB+","B+","BBB−"],"correct_option":2,"explanation":"S&P/Fitch coi BBB− là lowest IG notch; dưới ngưỡng là speculative grade theo convention thông dụng.","id":"Q02-01","los_ids":["CFA26-06-14-LOS02"]},{"stem":"Credit rating là gì?","options":["Ý kiến về relative credit risk, không bảo đảm thanh toán","Lời hứa trả nợ của agency","Dự báo giá bond chắc chắn"],"correct_option":0,"explanation":"Ratings thể hiện credit opinion, không phải insurance, investment advice hay guaranteed repayment.","id":"Q02-02","los_ids":["CFA26-06-14-LOS02"]},{"stem":"Một issuer BBB nhưng subordinated issue không bảo đảm có thể?","options":["Issue rating không thể khác","Có issue rating thấp hơn issuer rating","Bắt buộc issue luôn cao hơn issuer"],"correct_option":1,"explanation":"Recovery prospects và seniority của từng issue khác nhau, ảnh hưởng issue-specific credit rating.","id":"Q02-03","los_ids":["CFA26-06-14-LOS02"]},{"stem":"Corporate5.8% và matched Treasury3.5%; spread bằng?","options":["23bp","2,300bp","230bp"],"correct_option":2,"explanation":"5.8%−3.5%=2.3%=230 basis points, với 1bp bằng 0.01 percentage point.","id":"Q03-01","los_ids":["CFA26-06-14-LOS03"]},{"stem":"Spread duration5, credit spread widen 50bp; price approximation?","options":["−2.5%","+2.5%","−25%"],"correct_option":0,"explanation":"∆spread=.005 nên ∆P/P≈−5×.005=−0.025=−2.5%, bỏ qua duration curve và convexity.","id":"Q03-02","los_ids":["CFA26-06-14-LOS03"]},{"stem":"Trong recession, credit spreads thường có khuynh hướng?","options":["Không bao giờ phụ thuộc business cycle","Widen do PD và risk aversion tăng","Luôn thu hẹp"],"correct_option":1,"explanation":"Khi cash flow yếu và risk appetite thấp, investor đòi bù đắp cao hơn; magnitude khác theo rating và liquidity.","id":"Q03-03","los_ids":["CFA26-06-14-LOS03"]}],"flashcards":[{"front":"Credit risk và nguồn trả nợ — trình bày bản chất và công thức?","back":"Credit risk là khả năng người vay không thực hiện đầy đủ các nghĩa vụ thanh toán hoặc làm nhà đầu tư chịu lỗ do creditworthiness giảm. Giá trái phiếu chịu cả default risk và spread widening trước default; expected loss chỉ là một thành phần của yêu cầu lợi tức. Xem dòng tiền hoạt động, tài sản bảo đảm và nguồn refinancing.","id":"C01-01","los_ids":["CFA26-06-14-LOS01"]},{"front":"Probability of default (POD/PD) — trình bày bản chất và công thức?","back":"PD đo xác suất xảy ra sự kiện vỡ nợ trong một horizon xác định như 1 năm. Cần gắn definition of default, horizon, entity/issue, scenario và conditional/unconditional PD rõ ràng. Không đồng nhất PD với tỷ lệ mất toàn bộ giá trị.","id":"C01-02","los_ids":["CFA26-06-14-LOS01"]},{"front":"Loss given default (LGD) — trình bày bản chất và công thức?","back":"LGD là tỷ lệ tổn thất có điều kiện đã xảy ra default; recovery rate RR≈1−LGD trong mô hình đơn giản. Tài sản bảo đảm, seniority, collateral value, thời gian thu hồi và costs ảnh hưởng LGD. Một issuer có PD cao nhưng khoản nợ có bảo đảm vẫn có thể LGD thấp.","id":"C01-03","los_ids":["CFA26-06-14-LOS01"]},{"front":"Exposure at default (EAD) — trình bày bản chất và công thức?","back":"EAD là giá trị tiếp xúc dự kiến tại thời điểm default. Trái phiếu thường liên quan principal outstanding, accrued interest và recovery timing; revolving credit cần xét unused commitment drawdown. Không luôn dùng face 100 khi position mua discount hoặc có amortization.","id":"C01-04","los_ids":["CFA26-06-14-LOS01"]},{"front":"Issuer rating và issue rating — trình bày bản chất và công thức?","back":"Issuer rating phản ánh opinion về overall obligor creditworthiness; issue rating đánh giá khoản phát hành cụ thể, có thể chịu ảnh hưởng của security, priority of claims và guarantee. Không tự đồng nhất rating mọi issue với rating issuer. Trái phiếu secured/senior có recovery khác unsecured/subordinated.","id":"C02-01","los_ids":["CFA26-06-14-LOS02"]},{"front":"Credit rating là opinion, không phải bảo lãnh — trình bày bản chất và công thức?","back":"Rating thể hiện ý kiến phân loại relative credit risk dựa trên thông tin và methodology, không cam kết repayment, không phải trực tiếp investment recommendation hay exact expected loss number. Investor vẫn cần phân tích độc lập và xem suitability/liquidity.","id":"C02-02","los_ids":["CFA26-06-14-LOS02"]},{"front":"Rating scales và ngưỡng IG — trình bày bản chất và công thức?","back":"Các thang S&P/Fitch và Moody’s có ký hiệu khác nhau. Investment grade thường BBB−/Baa3 trở lên; BB+/Ba1 trở xuống thuộc speculative/high yield. Cần hiểu watchlist/outlook và transition risk, không coi một notch movement là deterministic spread change.","id":"C02-03","los_ids":["CFA26-06-14-LOS02"]},{"front":"Ứng dụng trong quản lý danh mục — trình bày bản chất và công thức?","back":"Ratings giúp định nghĩa eligible assets theo IPS, hạn chế exposure, định giá tương đối, giao dịch theo credit buckets và giám sát downgrade risk. Các portfolio mandates có giới hạn minimum rating hoặc cách tính composite ratings khi agencies disagree.","id":"C02-04","los_ids":["CFA26-06-14-LOS02"]},{"front":"Credit spread là gì — trình bày bản chất và công thức?","back":"Yield spread là khoảng cách giữa yield của bond risky và reference benchmark cùng tenor/curve convention. Spread phản ánh expected default loss, uncertainty/risk premium, market liquidity, taxes và supply-demand; không đồng nghĩa hoàn toàn actuarial expected loss. Cần cùng currency, duration và benchmark khi so sánh.","id":"C03-01","los_ids":["CFA26-06-14-LOS03"]},{"front":"Business cycle — trình bày bản chất và công thức?","back":"Khi GDP tăng trưởng, lợi nhuận và cash flows cải thiện, PD có thể giảm và spreads co hẹp; suy thoái làm khả năng trả nợ suy yếu và spreads giãn. High-yield thường nhạy với chu kỳ và equities hơn, investment grade có thể chịu ảnh hưởng rates nhiều hơn.","id":"C03-02","los_ids":["CFA26-06-14-LOS03"]},{"front":"Risk aversion và flight to quality — trình bày bản chất và công thức?","back":"Trong stress, investors mua government bonds làm benchmark yields giảm đồng thời yêu cầu credit premium tăng. Vì vậy corporate spread có thể giãn trong khi benchmark giảm; quan hệ đồng biến của risky total yields với Treasury không phải luôn đúng.","id":"C03-03","los_ids":["CFA26-06-14-LOS03"]},{"front":"Liquidity và market microstructure — trình bày bản chất và công thức?","back":"Issue size, trading frequency, market maker balance sheet, bid-ask spread, funding costs và dealer inventories ảnh hưởng liquidity premium. Cùng issuer rating và maturity, bond ít giao dịch thường spread cao hơn vì selling pressure/liquidation costs.","id":"C03-04","los_ids":["CFA26-06-14-LOS03"]}],"review_status":"targeted_CFAI_Kaplan_SAPP_math_and_browser_QA_not_exhaustive_full_PDF_verification"}]);
window.CFA_AUDIT_TOTALS={drafted:246,independently_reaudited:103,scope:"targeted source verification; not exhaustive"};
